ALTER TABLE public.paineis ADD COLUMN pode_emitir boolean NOT NULL DEFAULT true, ADD COLUMN pode_assinar boolean NOT NULL DEFAULT true, ADD COLUMN pode_comentar boolean NOT NULL DEFAULT true, ADD COLUMN ativo boolean NOT NULL DEFAULT true;
INSERT INTO public.paineis(user_id,nome,funcao,pode_emitir) SELECT ur.user_id, CASE ur.role::text WHEN 'admin' THEN 'ASAFE PEREIRA DA SILVA FELIX' WHEN 'pedagogica' THEN 'NUBIA PAULO DA COSTA ANDRADE' ELSE 'ADRIANA ROSADO MAIA OLIVEIRA DOMINGUES' END, CASE ur.role::text WHEN 'admin' THEN 'Administrador' WHEN 'pedagogica' THEN 'Gestora Pedagógica' ELSE 'Gestora Administrativa' END, ur.role::text='admin' FROM public.user_roles ur WHERE ur.role::text IN ('admin','pedagogica','administrativa') ON CONFLICT(user_id) DO NOTHING;
UPDATE public.paineis SET pode_emitir=false WHERE lower(nome||' '||funcao) LIKE '%monitoria%' OR lower(funcao) LIKE '%coordenação%';
CREATE OR REPLACE FUNCTION public.conta_ativa(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.paineis WHERE user_id=_uid AND NOT ativo) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_uid) $$;
CREATE OR REPLACE FUNCTION public.pode_emitir(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.conta_ativa(_uid) AND (public.has_role(_uid,'admin') OR (public.has_role(_uid,'emissor') AND EXISTS(SELECT 1 FROM public.paineis WHERE user_id=_uid AND pode_emitir))) $$;
CREATE OR REPLACE FUNCTION public.permissao_painel(_uid uuid,_acao text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.conta_ativa(_uid) AND (public.has_role(_uid,'admin') OR EXISTS(SELECT 1 FROM public.paineis WHERE user_id=_uid AND CASE _acao WHEN 'assinar' THEN pode_assinar WHEN 'comentar' THEN pode_comentar ELSE false END)) $$;
CREATE TABLE public.processos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), numero bigint GENERATED ALWAYS AS IDENTITY, tema text NOT NULL, assunto text NOT NULL, descricao text NOT NULL DEFAULT '', criado_por uuid NOT NULL DEFAULT auth.uid(), acessos uuid[] NOT NULL DEFAULT '{}', oficio_id uuid REFERENCES public.documentos(id), oficio_versao integer, aberto_em timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.processos TO authenticated; GRANT ALL ON public.processos TO service_role; ALTER TABLE public.processos ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.acesso_processo(_id uuid,_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.conta_ativa(_uid) AND EXISTS(SELECT 1 FROM public.processos WHERE id=_id AND (public.has_role(_uid,'admin') OR criado_por=_uid OR _uid=ANY(acessos))) $$;
CREATE POLICY processos_read ON public.processos FOR SELECT TO authenticated USING(public.acesso_processo(id,auth.uid()));
CREATE POLICY processos_insert ON public.processos FOR INSERT TO authenticated WITH CHECK(criado_por=auth.uid() AND public.pode_emitir(auth.uid()) AND aberto_em IS NULL);
CREATE POLICY processos_update ON public.processos FOR UPDATE TO authenticated USING(public.pode_emitir(auth.uid()) AND (criado_por=auth.uid() OR public.has_role(auth.uid(),'admin'))) WITH CHECK(public.pode_emitir(auth.uid()) AND (criado_por=auth.uid() OR public.has_role(auth.uid(),'admin')));
ALTER TABLE public.documentos ADD COLUMN versao integer NOT NULL DEFAULT 1, ADD COLUMN processo_id uuid REFERENCES public.processos(id);
ALTER TABLE public.solicitacoes_assinatura ADD COLUMN versao integer NOT NULL DEFAULT 1, ADD COLUMN finalidade text NOT NULL DEFAULT 'deferimento' CHECK(finalidade IN ('deferimento','ciencia'));
ALTER TABLE public.solicitacoes_assinatura DROP CONSTRAINT solicitacoes_assinatura_documento_id_gestora_key;
ALTER TABLE public.solicitacoes_assinatura ADD CONSTRAINT solicitacoes_por_versao UNIQUE(documento_id,gestora,versao);
ALTER TABLE public.solicitacoes_assinatura DROP CONSTRAINT solicitacoes_assinatura_decisao_check;
ALTER TABLE public.solicitacoes_assinatura ADD CONSTRAINT solicitacoes_decisao CHECK(decisao IN ('deferido','indeferido','ciente'));
CREATE TABLE public.documento_versoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),documento_id uuid NOT NULL REFERENCES public.documentos(id),versao integer NOT NULL,dados jsonb NOT NULL,emitido_em timestamptz,status text NOT NULL,assinaturas jsonb NOT NULL DEFAULT '[]',arquivado_em timestamptz NOT NULL DEFAULT now(),UNIQUE(documento_id,versao));
GRANT SELECT ON public.documento_versoes TO authenticated; GRANT ALL ON public.documento_versoes TO service_role; ALTER TABLE public.documento_versoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY versoes_read ON public.documento_versoes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.documentos WHERE id=documento_id));
ALTER TABLE public.documento_comentarios ADD COLUMN versao integer NOT NULL DEFAULT 1;
DROP POLICY comentarios_insert ON public.documento_comentarios;
CREATE POLICY comentarios_insert ON public.documento_comentarios FOR INSERT TO authenticated WITH CHECK(autor_id=auth.uid() AND public.permissao_painel(auth.uid(),'comentar') AND EXISTS(SELECT 1 FROM public.documentos d WHERE d.id=documento_id AND d.versao=documento_comentarios.versao AND (d.status='desenvolvendo' OR NOT public.pode_emitir(auth.uid()) OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY consulta_documentos ON public.documentos FOR SELECT TO authenticated USING(public.conta_ativa(auth.uid()) AND status='assinado' AND EXISTS(SELECT 1 FROM public.paineis WHERE user_id=auth.uid() AND NOT pode_emitir));
CREATE POLICY processo_documentos ON public.documentos FOR SELECT TO authenticated USING(processo_id IS NOT NULL AND public.acesso_processo(processo_id,auth.uid()));
CREATE POLICY processo_isolamento ON public.documentos AS RESTRICTIVE FOR ALL TO authenticated USING(public.conta_ativa(auth.uid()) AND (processo_id IS NULL OR public.acesso_processo(processo_id,auth.uid()))) WITH CHECK(public.conta_ativa(auth.uid()) AND (processo_id IS NULL OR public.acesso_processo(processo_id,auth.uid())));
CREATE POLICY conta_assinaturas ON public.solicitacoes_assinatura AS RESTRICTIVE FOR ALL TO authenticated USING(public.conta_ativa(auth.uid())) WITH CHECK(public.conta_ativa(auth.uid()));
CREATE POLICY registros_documento ON public.solicitacoes_assinatura FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.documentos d WHERE d.id=documento_id));
CREATE POLICY leitura_imagens ON public.assinaturas_gestoras FOR SELECT TO authenticated USING(public.conta_ativa(auth.uid()));
CREATE TABLE public.processo_anexos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),processo_id uuid NOT NULL REFERENCES public.processos(id),nome text NOT NULL,caminho text NOT NULL UNIQUE,criado_por uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.processo_anexos TO authenticated; GRANT ALL ON public.processo_anexos TO service_role; ALTER TABLE public.processo_anexos ENABLE ROW LEVEL SECURITY;
CREATE POLICY anexos_read ON public.processo_anexos FOR SELECT TO authenticated USING(public.acesso_processo(processo_id,auth.uid()));
CREATE POLICY anexos_insert ON public.processo_anexos FOR INSERT TO authenticated WITH CHECK(criado_por=auth.uid() AND public.pode_emitir(auth.uid()) AND public.acesso_processo(processo_id,auth.uid()) AND split_part(caminho,'/',1)=processo_id::text AND EXISTS(SELECT 1 FROM public.processos WHERE id=processo_id AND aberto_em IS NOT NULL));
CREATE POLICY processos_pdf_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='processos-pdfs' AND EXISTS(SELECT 1 FROM public.processos p WHERE p.id::text=split_part(name,'/',1) AND public.acesso_processo(p.id,auth.uid())));
CREATE POLICY processos_pdf_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='processos-pdfs' AND public.pode_emitir(auth.uid()) AND lower(storage.extension(name))='pdf' AND EXISTS(SELECT 1 FROM public.processos p WHERE p.id::text=split_part(name,'/',1) AND p.aberto_em IS NOT NULL AND public.acesso_processo(p.id,auth.uid())));
CREATE OR REPLACE FUNCTION public.proteger_documento_emissor() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF TG_OP='UPDATE' AND OLD.emitido_em IS NOT NULL AND (NEW.dados IS DISTINCT FROM OLD.dados OR NEW.numero<>OLD.numero OR NEW.ano<>OLD.ano OR NEW.tipo<>OLD.tipo OR NEW.assunto<>OLD.assunto OR NEW.processo_id IS DISTINCT FROM OLD.processo_id) THEN RAISE EXCEPTION 'Crie uma nova versão para editar documento emitido'; END IF;
IF TG_OP='UPDATE' AND (NEW.numero<>OLD.numero OR NEW.ano<>OLD.ano OR NEW.tipo<>OLD.tipo) THEN RAISE EXCEPTION 'Numeração reservada não pode mudar'; END IF;
IF NEW.processo_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.processos WHERE id=NEW.processo_id AND aberto_em IS NOT NULL) THEN RAISE EXCEPTION 'Processo não aberto'; END IF;
IF current_user IN ('postgres','service_role','supabase_admin') OR public.has_role(auth.uid(),'admin') THEN RETURN NEW; END IF;
IF TG_OP='INSERT' THEN NEW.criado_por:=auth.uid(); IF NEW.status<>'desenvolvendo' OR NEW.emitido_em IS NOT NULL OR NEW.analise_admin THEN RAISE EXCEPTION 'Estado inválido'; END IF;
ELSE IF NEW.criado_por IS DISTINCT FROM OLD.criado_por OR NEW.status IS DISTINCT FROM OLD.status OR NEW.emitido_em IS DISTINCT FROM OLD.emitido_em OR NEW.analise_admin IS DISTINCT FROM OLD.analise_admin OR NEW.versao<>OLD.versao OR NEW.enviado_analise_em IS DISTINCT FROM OLD.enviado_analise_em THEN RAISE EXCEPTION 'Alteração restrita'; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.salvar_documento(_id uuid,_dados jsonb,_processo uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.documentos; n integer; resultado uuid; BEGIN
IF NOT public.pode_emitir(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para emissão'; END IF;
IF _id IS NULL THEN
IF _processo IS NOT NULL AND (NOT public.acesso_processo(_processo,auth.uid()) OR NOT EXISTS(SELECT 1 FROM public.processos WHERE id=_processo AND aberto_em IS NOT NULL)) THEN RAISE EXCEPTION 'Processo não disponível'; END IF;
PERFORM pg_advisory_xact_lock(873420,(_dados->>'ano')::integer); SELECT coalesce(max(numero),0)+1 INTO n FROM public.documentos WHERE ano=(_dados->>'ano')::integer;
_dados:=jsonb_set(_dados,'{numero}',to_jsonb(n));
INSERT INTO public.documentos(tipo,numero,ano,assunto,dados,criado_por,processo_id) VALUES(_dados->>'tipo',n,(_dados->>'ano')::integer,_dados->>'assunto',_dados,auth.uid(),_processo) RETURNING id INTO resultado; RETURN resultado;
END IF;
SELECT * INTO d FROM public.documentos WHERE id=_id FOR UPDATE;
IF d.id IS NULL OR (NOT public.has_role(auth.uid(),'admin') AND (d.criado_por<>auth.uid() OR d.analise_admin)) OR (d.processo_id IS NOT NULL AND NOT public.acesso_processo(d.processo_id,auth.uid())) THEN RAISE EXCEPTION 'Documento não disponível'; END IF;
_dados:=_dados||jsonb_build_object('numero',d.numero,'ano',d.ano,'tipo',d.tipo);
IF d.emitido_em IS NOT NULL THEN
INSERT INTO public.documento_versoes(documento_id,versao,dados,emitido_em,status,assinaturas) SELECT d.id,d.versao,d.dados,d.emitido_em,d.status,coalesce(jsonb_agg(to_jsonb(s)) FILTER(WHERE s.id IS NOT NULL),'[]'::jsonb) FROM public.solicitacoes_assinatura s WHERE s.documento_id=d.id AND s.versao=d.versao;
UPDATE public.documentos SET emitido_em=NULL,status='desenvolvendo',analise_admin=false,enviado_analise_em=NULL,versao=versao+1 WHERE id=d.id;
END IF;
UPDATE public.documentos SET dados=_dados,assunto=_dados->>'assunto',updated_at=now() WHERE id=d.id; RETURN d.id; END $$;
CREATE OR REPLACE FUNCTION public.abrir_processo(_id uuid,_oficio uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.documentos; BEGIN
IF NOT public.pode_emitir(auth.uid()) OR NOT EXISTS(SELECT 1 FROM public.processos WHERE id=_id AND (criado_por=auth.uid() OR public.has_role(auth.uid(),'admin')) AND aberto_em IS NULL) THEN RAISE EXCEPTION 'Processo não disponível'; END IF;
SELECT * INTO d FROM public.documentos WHERE id=_oficio FOR UPDATE;
IF d.id IS NULL OR upper(d.tipo) NOT IN ('OFÍCIO','OFICIO') OR d.status<>'assinado' OR d.emitido_em IS NULL OR d.processo_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.solicitacoes_assinatura WHERE documento_id=d.id AND versao=d.versao AND gestora IN ('pedagogica','administrativa') AND assinado_em IS NOT NULL AND decisao='deferido') OR EXISTS(SELECT 1 FROM public.solicitacoes_assinatura WHERE documento_id=d.id AND versao=d.versao AND (assinado_em IS NULL OR decisao='indeferido')) OR (NOT public.has_role(auth.uid(),'admin') AND d.criado_por<>auth.uid()) THEN RAISE EXCEPTION 'Ofício exige deferimento da gestão e todas as assinaturas concluídas'; END IF;
UPDATE public.processos SET oficio_id=d.id,oficio_versao=d.versao,aberto_em=now() WHERE id=_id;
END $$;
CREATE OR REPLACE FUNCTION public.proteger_processo() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user NOT IN ('postgres','service_role','supabase_admin') THEN IF TG_OP='INSERT' AND (NEW.aberto_em IS NOT NULL OR NEW.oficio_id IS NOT NULL) THEN RAISE EXCEPTION 'Use a validação do ofício'; END IF; IF TG_OP='UPDATE' AND (NEW.aberto_em IS DISTINCT FROM OLD.aberto_em OR NEW.oficio_id IS DISTINCT FROM OLD.oficio_id OR NEW.oficio_versao IS DISTINCT FROM OLD.oficio_versao OR NEW.criado_por<>OLD.criado_por) THEN RAISE EXCEPTION 'Use a validação do ofício'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER proteger_processo BEFORE INSERT OR UPDATE ON public.processos FOR EACH ROW EXECUTE FUNCTION public.proteger_processo();
REVOKE ALL ON FUNCTION public.salvar_documento(uuid,jsonb,uuid),public.abrir_processo(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.salvar_documento(uuid,jsonb,uuid),public.abrir_processo(uuid,uuid) TO authenticated;
